def has_kind(adm, kind, target, dest):
    for a in adm or []:
        s = text(a)
        if kind and not s.startswith(kind + ' '):
            continue
        if target and target not in s:
            continue
        if dest and dest not in s:
            continue
        return True
    return False

def hook(ctx, nb):
    task_type = text(val(ctx, 'task.task_type', ''))
    target = text(val(ctx, 'task.target_type', ''))
    dest = text(val(ctx, 'task.destination_type', ''))
    if not target:
        return None
    need_op = need(task_type)
    if not need_op:
        nb['transformed'] = True
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    if need_op and target in act and act.startswith(need_op + ' ') and 'nothing happens' not in obs:
        nb['transformed'] = True
    if need_op and target in act and act.startswith('put ') and need_op in act and 'you put' in obs:
        nb['transformed'] = True
    inv = text(val(ctx, 'world.inventory', ''))
    carrying = bool(target in inv and 'not carrying' not in inv and 'nothing' not in inv)
    wrong = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and target not in inv)
    pc = val(ctx, 'world.placed_count', nb.get('placed_count', 0))
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if target in act and act.startswith('put ') and 'you put' in obs and (not dest or dest in act):
        pc = max(pc, nb.get('placed_count', 0) + 1)
    nb['placed_count'] = pc
    take_here = bool(target in obs and 'nothing' not in obs and 'not carrying' not in obs and 'you are not carrying' not in obs)
    if wrong:
        stage = 'wrong_inventory'
    elif carrying and need_op and not nb.get('transformed'):
        stage = 'transform'
    elif carrying and dest and has_kind(ctx.get('admissible') or [], 'put', target, dest):
        stage = 'put_target'
    elif carrying:
        stage = 'go_destination'
    elif take_here or bool(val(ctx, 'world.target_found', False)):
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    return None

