def hook(ctx, nb):
    stage = nb.get('stage')
    target = text(val(ctx, 'task.target_type', ''))
    dest = text(val(ctx, 'task.destination_type', ''))
    task_type = text(val(ctx, 'task.task_type', ''))
    need_op = need(task_type)
    if not target or not stage:
        return None
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target item. Do not place it as the goal; recover by setting it aside only if needed, then search for the requested ' + target + '.'
    elif stage == 'take_target':
        msg = 'A requested ' + target + ' is available here. Take it before continuing the room search.'
    elif stage == 'transform':
        place = 'sinkbasin'
        if need_op == 'heat':
            place = 'microwave'
        if need_op == 'cool':
            place = 'fridge'
        msg = 'You are carrying the ' + target + '. Use the available ' + need_op + ' action at the ' + place + ' before putting it at the destination.'
    elif stage == 'put_target':
        msg = 'You are at the destination with the ' + target + '. Use the admissible put action for the ' + dest + ' now.'
    elif stage == 'go_destination':
        msg = 'Carry the ' + target + ' to the ' + dest + ' and put it there; avoid taking unrelated objects.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

